  /* Styling untuk gambar di kanan agar bentuknya tetap sama seperti Elementor */
  #dynamic-svc-img {
    width: 100%;
    border-radius: 24px;
    object-fit: cover;
    transition: opacity 0.3s ease; /* Bikin transisi fade mulus */
  }
</style>

<img id="dynamic-svc-img" src="https://csmilebali.id/wp-content/uploads/2026/05/s4_img1.png" alt="CSmile service">

<script>
  document.addEventListener('DOMContentLoaded', () => {
    const cards = document.querySelectorAll('.svc-card');
    const targetImg = document.getElementById('dynamic-svc-img');
    
    // Array berisi link gambar sesuai urutan kartu
    const imgUrls = [
      "https://csmilebali.id/wp-content/uploads/2026/05/s4_img1.png", // Index 0: Untuk Service Card 1
      "https://csmilebali.id/wp-content/uploads/2026/05/s4_img2.png"  // Index 1: Untuk Service Card 2
    ];

    cards.forEach((card, index) => {
      card.addEventListener('click', () => {
        // Reset efek nyala di kartu
        cards.forEach(c => c.classList.remove('svc-active'));
        card.classList.add('svc-active');
        
        // Proses ganti gambar dengan animasi fade
        targetImg.style.opacity = 0;
        setTimeout(() => {
          targetImg.src = imgUrls[index];
          targetImg.style.opacity = 1;
        }, 300); // Ganti gambar setelah fade out selesai
      });
    });
  });
</script>","_element_width":"inherit","_flex_align_self":"center","_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[],"widgetType":"html"}],"isInner":true},{"id":"79a6e93","elType":"widget","settings":{"html":"<style>
  /* Sembunyikan gambar default & beri animasi transisi */
  .svc-img { 
    transition: opacity 0.3s ease; 
    opacity: 0; 
  }
  /* Munculkan gambar yang aktif */
  .svc-img.svc-img-active { 
    opacity: 1; 
    z-index: 2; 
  }
  
  /* Bikin kursor jadi tangan pas hover kartu kiri */
  .svc-card { 
    cursor: pointer; 
    transition: all 0.3s ease; 
    opacity: 0.8; 
  }
  /* Efek menyala buat kartu yang sedang dipilih */
  .svc-card.svc-active { 
    opacity: 1; 
    border: 1px solid rgba(252, 95, 43, 0.3); 
  }
</style>

<script>
  document.addEventListener('DOMContentLoaded', () => {
    // Tangkap semua kartu dan gambar
    const cards = document.querySelectorAll('.svc-card');
    const imgs = document.querySelectorAll('.svc-img');

    cards.forEach((card, index) => {
      card.addEventListener('click', () => {
        // 1. Reset class aktif dari semua kartu dan gambar
        cards.forEach(c => c.classList.remove('svc-active'));
        imgs.forEach(i => i.classList.remove('svc-img-active'));

        // 2. Tambah class aktif ke kartu yang di-klik dan gambar pasangannya
        card.classList.add('svc-active');
        if(imgs[index]) imgs[index].classList.add('svc-img-active');
      });
    });
  });
</script>","_margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"_element_width":"auto","_flex_order":"end","_flex_align_self":"flex-end","_flex_size":"shrink"},"elements":[],"widgetType":"html"}],"isInner":true}],"isInner":false},{"id":"81c2c89","elType":"container","settings":{"flex_direction":"column","background_background":"classic","padding":{"unit":"px","top":"70","right":"0","bottom":"70","left":"0","isLinked":false},"css_classes":"made-selection","custom_css":"/* --- FIX 1: Marquee Animation --- */
selector .lab-marquee-wrapper {
  overflow: hidden;
  width: 100%;
}
selector .made-main-marquee-block {
  display: flex;
  flex-direction: row; /* Paksa baris ke samping */
  flex-wrap: nowrap;
  overflow: hidden;
}
selector .lab-marquee-track {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  flex: none;
  animation: labMarquee 20s linear infinite;
}
selector .lab-marquee-track:hover {
  animation-play-state: paused;
}
selector .image-marquee {
  max-height: 320px !important;
  width: auto !important; /* Matikan paksaan width 100% dari WordPress */
  max-width: none !important; /* Bebaskan gambar agar bisa memanjang */
  object-fit: cover;
  flex-shrink: 0;
  margin-right: 20px; /* Beri sedikit jarak antar gambar agar tidak dempet */
}
@keyframes labMarquee {
  0%   { transform: translateX(0); }
  100% { transform: translateX(-100%); }
}

/* --- FIX 2: Premium Feature Hover Bar (Anti-Loncat) --- */
selector .premium-material-hover-block {
  position: relative;
  cursor: pointer;
}
selector .premium-material-div {
  height: 3px;
  background-color: #e5b283;
  width: 100%; /* Set full sejak awal */
  transform: scaleX(0); /* Sembunyikan dengan cara dikempeskan */
  transform-origin: left; /* Mulai mekar dari arah kiri */
  transition: transform 0.4s ease;
}
selector .premium-material-hover-block:hover .premium-material-div {
  transform: scaleX(1); /* Mekarkan penuh saat di-hover */
}

/* --- Icon circle (reuse) --- */
selector .steps-image-block {
  background-color: #ffece6;
  border-radius: 100px;
  min-width: 60px;
  width: 60px;
  height: 60px;
  padding: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
}

/* --- Responsive --- */
@media (max-width: 991px) {
  selector .premium-materials-main-block {
    flex-direction: column;
  }
}
@media (min-width: 1920px) {
  selector .image-marquee { max-height: 548px !important; }
}
@media (max-width: 479px) {
  selector .image-marquee { max-height: 280px !important; }
