 /* Wadah utama: Kunci lebarnya di 450px agar tidak meledak di desktop */
  .ba-main-wrapper {
    width: 100%;
    max-width: 450px !important; 
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    box-sizing: border-box;
  }

  /* Slider container: Hapus yang dobel, jadikan satu saja */
  .ba-slider-container {
    position: relative;
    width: 100%;
    aspect-ratio: 3 / 4;
    border-radius: 16px;
    overflow: hidden;
    background-color: #f5f5f5;
  }
  
  .my-slider-pane {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    visibility: hidden;
    z-index: 1;
    transition: opacity 0.4s ease;
  }
  
  .my-slider-pane.active-pane {
    position: relative;
    opacity: 1;
    visibility: visible;
    z-index: 2;
  }

  .my-slider-pane > div,
  .my-slider-pane .bafg-twentytwenty-container {
    height: 100% !important;
  }

  .my-slider-pane img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    object-position: center !important;
    display: block;
  }
  

  .ba-thumbnails {
    display: flex;
    gap: 4px;
    justify-content: center;
    align-items: flex-end;
    margin-top: -36px !important;
    padding: 0 10px;
    position: relative;
    z-index: 10;
    flex-wrap: wrap;
    width: 100%;
    box-sizing: border-box;
  }

  .ba-thumb {
    width: 56px !important;
    height: 64px !important;
    max-width: 56px !important;
    max-height: 64px !important;
    object-fit: cover !important;
    object-position: center !important;
    box-sizing: border-box !important;
    border: 3px solid #4d4d4d !important;
    border-radius: 16px !important;
    margin: 0 !important;
    padding: 0 !important;
    cursor: pointer;
    opacity: 0.7;
    transition: all 0.3s ease;
    flex-shrink: 0;
  }
  
  .ba-thumb.active-thumb {
    width: 56px !important;
    height: 64px !important;
    max-width: 56px !important;
    max-height: 64px !important;
    border-color: #fc5f2b !important;
    opacity: 1 !important;
  }


@media (max-width: 479px) {
    .ba-thumbnails {
      flex-wrap: nowrap !important; /* Paksa agar selalu sebaris */
      gap: 3px; /* Kurangi jarak sedikit */
      padding: 0 5px; 
    }

    /* Kecilkan ukuran semua thumbnail agar muat 7 buah di layar HP */
    .ba-thumb,
    .ba-thumb.active-thumb {
      width: 42px !important;
      height: 50px !important;
      max-width: 42px !important;
      max-height: 50px !important;
      border-width: 2px !important; /* Border ditipiskan agar proporsional */
      border-radius: 8px !important; 
    }
  }

</style>

<div class="ba-main-wrapper">
  
  <div class="ba-slider-container">
    <div class="my-slider-pane active-pane" id="ba-pane-1">[bafg id="412"]</div>
    <div class="my-slider-pane" id="ba-pane-2">[bafg id="427"]</div>
    <div class="my-slider-pane" id="ba-pane-3">[bafg id="428"]</div>
    <div class="my-slider-pane" id="ba-pane-4">[bafg id="429"]</div>
    <div class="my-slider-pane" id="ba-pane-5">[bafg id="430"]</div>
    <div class="my-slider-pane" id="ba-pane-6">[bafg id="431"]</div>
    <div class="my-slider-pane" id="ba-pane-7">[bafg id="432"]</div>
  </div>

  <div class="ba-thumbnails">
    <img src="https://csmilebali.id/wp-content/uploads/2026/05/s6_image1_after-scaled.png" class="ba-thumb active-thumb" data-target="ba-pane-1">
    <img src="https://csmilebali.id/wp-content/uploads/2026/05/s6_image2_after.png" class="ba-thumb" data-target="ba-pane-2">
    <img src="https://csmilebali.id/wp-content/uploads/2026/05/s6_image3_after.png" class="ba-thumb" data-target="ba-pane-3">
    <img src="https://csmilebali.id/wp-content/uploads/2026/05/s6_image4_after.png" class="ba-thumb" data-target="ba-pane-4">
    <img src="https://csmilebali.id/wp-content/uploads/2026/05/s6_image5_after.png" class="ba-thumb" data-target="ba-pane-5">
    <img src="https://csmilebali.id/wp-content/uploads/2026/05/s6_image6_after.png" class="ba-thumb" data-target="ba-pane-6">
    <img src="https://csmilebali.id/wp-content/uploads/2026/05/s6_image7_after.png" class="ba-thumb" data-target="ba-pane-7">
  </div>

</div>

<script>
  document.addEventListener('DOMContentLoaded', () => {
    const thumbs = document.querySelectorAll('.ba-thumb');
    const panes = document.querySelectorAll('.my-slider-pane');

    thumbs.forEach(thumb => {
      thumb.addEventListener('click', () => {
        // Matikan semua pane & hapus class aktif di thumbnail
        thumbs.forEach(t => t.classList.remove('active-thumb'));
        panes.forEach(p => p.classList.remove('active-pane'));

        // Aktifkan yang di-klik
        thumb.classList.add('active-thumb');
        const targetId = thumb.getAttribute('data-target');
        const targetPane = document.getElementById(targetId);
        if (targetPane) targetPane.classList.add('active-pane');
      });
    });
  });
</script>"},"elements":[],"widgetType":"html"}],"isInner":true},{"id":"a1ccbd6","elType":"container","settings":{"content_width":"full","width":{"unit":"%","size":100,"sizes":[]},"width_tablet":{"unit":"%","size":"","sizes":[]},"width_mobile":{"unit":"%","size":"","sizes":[]},"padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"padding":{"unit":"px","top":"30","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[{"id":"ae09330","elType":"widget","settings":{"editor":"Stop Dreaming, Start Smiling!

