g":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[{"id":"5718d93","elType":"widget","settings":{"title":"Real Transformations, Real Confidence.","align":"center","typography_typography":"custom","typography_font_family":"Outfit","typography_font_size":{"unit":"px","size":35,"sizes":[]},"typography_font_weight":"600","typography_line_height":{"unit":"em","size":1.6,"sizes":[]},"__globals__":{"typography_typography":""},"typography_line_height_mobile":{"unit":"em","size":1.2,"sizes":[]},"_animation":"fadeInUp"},"elements":[],"widgetType":"heading"}],"isInner":true},{"id":"a1ab4f8","elType":"container","settings":{"content_width":"full","flex_justify_content":"center","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[{"id":"a6b1b6f","elType":"widget","settings":{"html":"<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.css">

<style>
  /* --- WRAPPER UTAMA --- */
  .s7-carousel-wrapper {
    width: 100%;
    max-width: 1200px; /* Lebarkan sedikit agar di desktop enak dilihat */
    margin: 0 auto;
    padding: 40px 0;
    overflow: hidden;
  }

  .swiper {
    width: 100%;
    height: 480px; 
  }

  /* --- STYLING SLIDE --- */
  /* Kita biarkan Swiper yang mengatur lebarnya (width), kita hanya atur efeknya */
  .swiper-slide {
    height: 100%;
    border-radius: 12px;
    overflow: hidden;
    display: flex;
    justify-content: center;
    align-items: center;
    
    /* Efek Tidak Aktif */
    transform: scale(0.85); /* Dikecilkan sedikit agar jelas bedanya */
    opacity: 0.5;
    filter: blur(1.5px); /* Efek blur untuk slide yang di pinggir */
    transition: all 0.4s ease;
  }

  .swiper-slide video {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 12px;
  }

  /* --- EFEK SLIDE AKTIF (TENGAH) --- */
  .swiper-slide-active {
    transform: scale(1);
    opacity: 1;
    filter: blur(0px);
    z-index: 2; /* Pastikan selalu berada di atas */
  }

  /* --- RESPONSIVE FIX --- */
  /* Di layar HP (di bawah 480px), kita buat tinggi videonya menyesuaikan agar tidak kepanjangan */
  @media (max-width: 479px) {
    .swiper {
      height: 420px; 
    }
  }
</style>

<div class="s7-carousel-wrapper">
  <div class="swiper">
    <div class="swiper-wrapper">
      
      <div class="swiper-slide">
