        <div class="testimonial-description">${data.text}</div>
      </div>
    `;

    const htmlRow1 = reviewsBaris1.map(buildCard).join('');
    const htmlRow2 = reviewsBaris2.map(buildCard).join('');
    const injectHTML = (id, html) => {
      const el = document.getElementById(id);
      if (el) el.innerHTML = html;
    };

    injectHTML("marquee-row-1a", htmlRow1);
    injectHTML("marquee-row-1b", htmlRow1);
    
    injectHTML("marquee-row-2a", htmlRow2);
    injectHTML("marquee-row-2b", htmlRow2);
  });
</script>","custom_css":".testimonial-main-content-block {
  border: 1px solid #d9d9d9;
  border-radius: 12px;
  width: 600px;
  height: 325px;
  margin-right: 24px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  flex-shrink: 0;
  background: #fff;
  box-sizing: border-box;
}

.testimonial-heading-blocks {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  width: 100%;
}

.author-info-block {
  display: flex;
  gap: 16px;
  align-items: center;
}

.author-image {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  object-fit: cover;
}

.author-name {
  font-family: 'Cal Sans', sans-serif;
  font-size: 24px;
  line-height: 120%;
  color: #100800;
  margin-bottom: 4px;
}

.author-state {
  color: #d78e4b; /* Warna Gold Accent */
  font-family: 'Hanken Grotesk', sans-serif;
  font-size: 16px;
  line-height: 100%;
}

.rating {
  width: 100px; /* Lebar gambar bintang */
  height: auto;
}

.testimonial-description {
  color: #574f48;
  font-family: 'Hanken Grotesk', sans-serif;
  font-size: 16px;
  line-height: 160%;
  overflow: auto; /* Kalau teks kepanjangan bisa di-scroll di dalam card */
}

.testimonial-wrapper-section {
  width: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 30px; /* Jarak antara baris 1 dan baris 2 */
}

.testimonial-first-marquee-main-block {
  display: flex;
  width: max-content;
}

.testimonial-first-marquee-block {
  display: flex;
  flex: none;
  animation: reviewScrollLeft 40s linear infinite;
}

/* Baris kedua scroll ke arah sebaliknya (Kanan) */
.testimonial-first-marquee-main-block.second-testimonials .testimonial-first-marquee-block {
  animation: reviewScrollRight 40s linear infinite;
}

/* Keyframes Animasi */
@keyframes reviewScrollLeft {
  0% { transform: translateX(0); }
  100% { transform: translateX(-100%); }
}
@keyframes reviewScrollRight {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(0); }
}

/* Mobile Responsive */
@media (max-width: 479px) {
  .testimonial-main-content-block {
    width: 320px;
    height: 350px;
    padding: 15px;
  }
  .author-name { font-size: 20px; }
  .author-state, .testimonial-description { font-size: 14px; }
}"},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"510b32a","elType":"container","settings":{"flex_direction":"column","boxed_width":{"unit":"px","size":1920,"sizes":[]},"background_background":"classic","background_image":{"url":"https://csmilebali.id/wp-content/uploads/2026/06/s9_bg.png","id":670,"size":"2048x2048","alt":"","source":"library"},"background_position":"center center","background_size":"cover","padding":{"unit":"px","top":"70","right":"20","bottom":"70","left":"20","isLinked":false},"_element_id":"contact","css_classes":"contact-section","custom_css":"/* Glassmorphic form container */
selector .consult-form {
  background: linear-gradient(135deg, rgba(127, 178, 198, 0.5), rgba(159, 181, 191, 0.5));
  border-radius: 20px;
  padding:40px;
  max-width: 600px;
}
/* Form labels */
selector .field-label {
  font-family: 'Cal Sans', sans-serif;
  font-weight: 400;
  font-size: 16px;
  line-height: 14px;
  color: #ffffff;
  display: block;
  margin: 14px 0 6px;
}
selector .text-span, selector .text-span-2 {
  color: #ff1a1a;
}
/* Form inputs */
selector .text-field,
selector .textarea {
  border: 1px solid rgba(209, 209, 209, 0.2);
  border-radius: 12px;
  padding: 14px 16px;
  font-family: 'Hanken Grotesk', sans-serif;
  font-size: 14px;
  line-height: 1.4;
  width: 100%;
}
selector .text-field:focus,
selector .textarea:focus {
  border-color: #ff5a1f;
  box-shadow: 0 0 0 2px rgba(255, 90, 31, 0.2);
  outline: none;
}
selector .textarea {
  min-height: 120px;
  resize: none;
}
/* Submit button */
selector .submit-button {
  background: #ff5a1f;
  border-radius: 14px;
  padding: 16px;
  font-size: 16px;
  font-weight: 600;
  width: 100%;
  margin-top: 18px;
  color: #ffffff;
  border: none;
  cursor: pointer;
}
selector .submit-button:hover {
  background: #ff743a;
}
/* Footnote */
selector .text-block-39 {
  font-family: 'Hanken Grotesk', sans-serif;
  font-size: 12px;
  opacity: 0.9;
  margin-top: 12px;
  color: #ffffff;
  text-align: center;
}
/* Required asterisk color (if using Elementor Pro Form) */
selector .elementor-mark-required .elementor-field-label:after {
  color: #ff1a1a !important;
}
/* Tablet: stack */
@media (max-width: 991px) {
  selector > .elementor-container {
    flex-direction: column;
  }
}
@media (max-width: 479px) {
  selector .consult-form {
    padding: 24px;
    border-radius: 16px;
  }
}
@media (min-width: 1920px) {
  selector { padding: 144px 20px; }
}","__globals__":{"background_color":"globals/colors?id=5f6fa0e"}},"elements":[{"id":"1bf1a71","elType":"container","settings":{"boxed_width":{"unit":"px","size":1480,"sizes":[]},"flex_direction":"row","flex_justify_content":"center","flex_align_items":"center","flex_gap":{"column":"70","row":"70","isLinked":true,"unit":"px","size":70},"padding":{"unit":"px","top":"70","right":"20","bottom":"70","left":"20","isLinked":false},"padding_mobile":{"unit":"px","top":"50","right":"0","bottom":"50","left":"0","isLinked":false}},"elements":[{"id":"0d00220","elType":"container","settings":{"width":{"unit":"%","size":60,"sizes":[]},"boxed_width":{"unit":"px","size":646,"sizes":[]},"flex_direction":"column","flex_gap":{"column":"38","row":"38","isLinked":true,"unit":"px","size":38},"padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[{"id":"bc267e7","elType":"container","settings":{"content_width":"full","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[{"id":"2453ab1","elType":"widget","settings":{"title":"Start Your Smile Journey Today","typography_typography":"custom","typography_font_family":"Outfit","typography_font_size":{"unit":"px","size":40,"sizes":[]},"typography_font_weight":"600","typography_line_height":{"unit":"em","size":1.6,"sizes":[]},"__globals__":{"typography_typography":"","title_color":"globals/colors?id=6094401"}},"elements":[],"widgetType":"heading"},{"id":"ef45e0a","elType":"widget","settings":{"editor":"Fill out the form below and our team will contact you within 24 hours with a personalized treatment plan and quote.","typography_typography":"custom","typography_font_family":"Hanken Grotesk","typography_font_size":{"unit":"px","size":19,"sizes":[]},"typography_font_weight":"400","typography_line_height":{"unit":"em","size":1.6,"sizes":[]},"__globals__":{"typography_typography":"","text_color":"globals/colors?id=6094401"}},"elements":[],"widgetType":"text-edito