ustom_css":"/* Glassmorphic form container */
selector .consult-form {
  background: linear-gradient(135deg, rgba(127, 178, 198, 0.5), rgba(159, 181, 191, 0.5));
  border-radius: 20px;
  padding:40px;
  max-width: 600px;
}
/* Form labels */
selector .field-label {
  font-family: 'Cal Sans', sans-serif;
  font-weight: 400;
  font-size: 16px;
  line-height: 14px;
  color: #ffffff;
  display: block;
  margin: 14px 0 6px;
}
selector .text-span, selector .text-span-2 {
  color: #ff1a1a;
}
/* Form inputs */
selector .text-field,
selector .textarea {
  border: 1px solid rgba(209, 209, 209, 0.2);
  border-radius: 12px;
  padding: 14px 16px;
  font-family: 'Hanken Grotesk', sans-serif;
  font-size: 14px;
  line-height: 1.4;
  width: 100%;
}
selector .text-field:focus,
selector .textarea:focus {
  border-color: #ff5a1f;
  box-shadow: 0 0 0 2px rgba(255, 90, 31, 0.2);
  outline: none;
}
selector .textarea {
  min-height: 120px;
  resize: none;
}
/* Submit button */
selector .submit-button {
  background: #ff5a1f;
  border-radius: 14px;
  padding: 16px;
  font-size: 16px;
  font-weight: 600;
  width: 100%;
  margin-top: 18px;
  color: #ffffff;
  border: none;
  cursor: pointer;
}
selector .submit-button:hover {
  background: #ff743a;
}
/* Footnote */
selector .text-block-39 {
  font-family: 'Hanken Grotesk', sans-serif;
  font-size: 12px;
  opacity: 0.9;
  margin-top: 12px;
  color: #ffffff;
  text-align: center;
}
/* Required asterisk color (if using Elementor Pro Form) */
selector .elementor-mark-required .elementor-field-label:after {
  color: #ff1a1a !important;
}
/* Tablet: stack */
@media (max-width: 991px) {
  selector > .elementor-container {
    flex-direction: column;
  }
}
@media (max-width: 479px) {
  selector .consult-form {
    padding: 24px;
    border-radius: 16px;
  }
}
@media (min-width: 1920px) {
  selector { padding: 144px 20px; }
